css:
#tongsci2-2-1-3-3-cover .frame { flex-direction: row; gap: 72px; }
#tongsci2-2-1-3-3-cover .col-text { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 28px; }
#tongsci2-2-1-3-3-cover h1 { font-size: 112px; }
#tongsci2-2-1-3-3-cover .hero-pen { font-size: 56px; transform: rotate(-1.2deg); transform-origin: left center; margin-top: -6px; }
#tongsci2-2-1-3-3-cover .footer { left: 1100px; right: 300px; }
#tongsci2-2-1-3-3-cover .lesson-chip {
  align-self: flex-start; display: inline-flex; gap: 14px; align-items: baseline;
  border: 2px solid var(--ink); border-radius: 999px; padding: 6px 22px; font-size: 26px; font-weight: 600;
}
#tongsci2-2-1-3-3-cover .lesson-chip span { font-family: var(--f-mono); font-size: 22px; color: var(--ink-2); font-weight: 500; }
#tongsci2-2-1-3-3-cover .goals { display: flex; flex-direction: column; gap: 18px; max-width: 980px; }
#tongsci2-2-1-3-3-cover .goals-label { font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--ink-2); }
#tongsci2-2-1-3-3-cover .goal { display: grid; grid-template-columns: 52px 1fr; gap: 6px; font-size: 30px; line-height: 1.42; }
#tongsci2-2-1-3-3-cover .goal .no { font-family: var(--f-display); font-weight: 700; color: var(--ink-2); }
#tongsci2-2-1-3-3-cover .today {
  margin-top: 6px; padding: 20px 28px; background: var(--paper-2); border: 2px solid var(--ink);
  border-radius: 6px; box-shadow: 6px 6px 0 var(--ink); font-size: 32px; line-height: 1.45;
}
#tongsci2-2-1-3-3-cover .today .tag { display: block; font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--accent); margin-bottom: 6px; }
#tongsci2-2-1-3-3-cover .col-fig { flex: 0 0 700px; display: flex; flex-direction: column; gap: 14px; padding-top: 24px; }
#tongsci2-2-1-3-3-cover .fig-caption .cap { font-size: 21px; line-height: 1.4; }
#tongsci2-2-1-3-3-cover .share-card { padding: 60px 30px 26px; display: flex; flex-direction: column; gap: 18px; }
#tongsci2-2-1-3-3-cover .share-card h3 { margin: 0; font: 700 34px/1.3 var(--f-display); color: var(--ink); text-wrap: balance; }

js:
/* tongsci2.2-1-3.3.cover */
(function () {
  'use strict';
  const {part}=window.Deck;
  const join=(...m)=>RxT.join(...m);
 function cover(root,mod){ root.querySelectorAll('.share-opts button').forEach(b=>b.addEventListener('click',()=>{root.querySelectorAll('.share-opts button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}));return mod.mount(root); }
 function gal(root){root.querySelector('.gv').addEventListener('gv-pick',e=>root.querySelectorAll('.ab-row').forEach(x=>x.classList.toggle('on',x.dataset.k===e.detail.b.dataset.row)));return RxT.gallery(root);}
 function exp(root,mod){return ClimateUI.mount(root,mod);}
  part('tongsci2-2-1-3-3-cover',r=>cover(r,window.Coast));
})();
